import { randomString } from '@splendidlabz/utils/dom'
import { SvelteMap } from 'svelte/reactivity'

export function MapStore() {
  const map = new SvelteMap()

  return {
    map,
    getEntry: getEntry.bind(null, map),
    getEntryBy: getEntryBy.bind(null, map),
    getEntries: getEntries.bind(null, map),
    createEntry: createEntry.bind(null, map),
    updateEntry: updateEntry.bind(null, map),
    createAIEntry: createAIEntry.bind(null, map),
    updateAIEntry: updateAIEntry.bind(null, map),
    deleteEntry: deleteEntry.bind(null, map),
  }
}

export function getEntry(map, key) {
  return map.get(key)
}

export function getEntryBy(map, property, value) {
  const entries = getEntries(map)
  const entry = entries.find(entry => entry[property] === value)
  return entry
}

export function getEntries(map) {
  return Array.from(map.values())
}

export function createEntry(map, key, data) {
  const id = key || randomString(10)
  const entry = $state({ id, ...data, updatedAt: new Date() })
  map.set(key, entry)
  return entry
}

export function updateEntry(map, key, set) {
  const entry = getEntry(map, key)
  if (!entry) return
  Object.assign(entry, { ...set, updatedAt: new Date() })
  return entry
}

export function createAIEntry(map, key, data) {
  return createEntry(map, key, data)
}

export function updateAIEntry(map, key, set = {}) {
  const entry = getEntry(map, key)
  if (!entry) return

  if (!entry.content) entry.content = '' // prevent undefined message
  const { content = '', tool_calls = [], usage_metadata = {} } = set

  if (content) entry.content += content
  if (tool_calls?.length > 0) {
    entry.tool_calls.push(...tool_calls)
  }
  if (usage_metadata) entry.usage_metadata = usage_metadata

  entry.updatedAt = new Date()
  return entry
}

export function deleteEntry(map, key) {
  map.delete(key)
}
